class RndDMode(CommonPage):
    _instance_dict = {}

    def __init__(self):
        if not self._instance_dict:
            self._instance_dict = {"Vendor Parameters": VendorParametersPage(),
                                   "5G Performance Test": PerformanceTestPage()}
        super(RndDMode, self).__init__(self._instance_dict)


class VendorParametersPage(object):
    MENU_ROUTE_LIST = ['R&D Mode', 'Vendor Parameters']

    def __init__(self):
        self._view_panel = VendorParametersPageViewPanel()

    def download_default_file(self, timeout=60):
        """
        Method for downloading default file under Vendor Parameters page
        :param timeout: int, timeout
        :return: str, file path
        """
        return self._view_panel.download_default_file(timeout)

    def load_vendor_file_and_validate(self, file_path, timeout=60):
        """
        Method for loading vendor file and validate
        :param file_path: str, vendor file path
        :param timeout: int, timeout
        :return: str, status after validating
        """
        return self._view_panel.load_vendor_file_and_validate(file_path, timeout)


class VendorParametersPageViewPanel(ViewPanel):
    _DOWNLOAD_DEFAULT_FILE_XPATH = '//vendor-parameters-download-button//button'
    _LOAD_VENDOR_FILE_BUTTON_SCRIPT = 'vendor-parameters-load-button input'
    _LOAD_VENDOR_FILE_BUTTON_XPATH = '//vendor-parameters-load-button//input'
    _VALIDATE_BUTTON_XPATH = '//vendor-parameters-validate-button//button'
    _FEEDBACK_XPATH = '//div[@class="feedback-section"]//span'
    OPERATION_ONGOING = 'Operation ongoing...'

    def __init__(self):
        super(VendorParametersPageViewPanel, self).__init__()

    def download_default_file(self, timeout):
        start_time = time.time()
        self.click_enabled_element((By.XPATH, self._DOWNLOAD_DEFAULT_FILE_XPATH), timeout)
        return self.download_files(start_time)

    def load_vendor_file_and_validate(self, file_path, timeout=60):

        self.load_file_from_hidden_button(self._LOAD_VENDOR_FILE_BUTTON_SCRIPT,
                                          self._LOAD_VENDOR_FILE_BUTTON_XPATH, file_path, timeout)
        self.click_enabled_element((By.XPATH, self._VALIDATE_BUTTON_XPATH), timeout)

        self.wait_for_text_not_present_in_element((By.XPATH, self._FEEDBACK_XPATH), self.OPERATION_ONGOING, timeout)
        return self.get_text_by_xpath(self._FEEDBACK_XPATH)


class PerformanceTestPage(object):
    MENU_ROUTE_LIST = ['R&D Mode', '5G Performance Test']

    def __init__(self):
        self._view_panel = PerformanceTestPageViewPanel()

    def start_pusch_test(self, local_cell, frc_index, do_rate, do_type, rep_time_int,
                         beam_id=None, ru_mode=None, physical_cell_id=None, bb_selector=None,
                         prb_offset=None, timeout=15):
        """
        Starts 5G Performance PUSCH test on 5G Performance Test Page.
        :param local_cell: Name of local cell for which test will be started.
        :type local_cell: str
        :param frc_index: Name of frc index which will be used during test.
        :type frc_index: str
        :param do_rate: Digital output rate, to be chosen between with exact name,
        for example "Bitrate_115dot2K" or "Bitrate_460dot8K".
        :type do_rate: str
        :param do_type: Digital output type parameter which will be used during test.
        To be passed as exact value, for example "SerialKeysight" or "SerialRs".
        :type do_type: str
        :param rep_time_int: Reporting time interval (in seconds) between
        following measures.
        :type rep_time_int: int
        :param beam_id: ID of beam pattern  which will be used during test, None at default.
        If not provided, then method won't change default value on WebUI.
        :type beam_id: int
        :param ru_mode: Radio Unit mode, to be passed as exact value, e.g. "NR_Only".
        None at default, if not provided, then method won't change default value on WebUI.
        :type ru_mode: str
        :param physical_cell_id: value of Physical cell ID which will be used during test.
        None at default, if not provided, then method won't change default value on WebUI.
        :type physical_cell_id: int
        :param bb_selector: BB Selector parameter which will be used during test.
        None at default, if not provided, then method won't change default value on WebUI.
        :type bb_selector: int
        :param prb_offset: PRB Offset parameter which will be used during test.
        None at default, if not provided, then method won't change default value on WebUI.
        :type prb_offset: int
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        """
        self._view_panel.start_pusch_test(local_cell, frc_index, do_rate, do_type, rep_time_int,
                                          beam_id, ru_mode, physical_cell_id, bb_selector,
                                          prb_offset, timeout)

    def start_pucch_test(self, local_cell, rep_time_int, reception_slot, expectation_slot, f0_sys_num, f2_test_type,
                         beam_id, ru_mode, physical_cell_id, pucch_format, timeout):
        """
        Starts 5G Performance PUCCH test on 5G Performance Test Page.
        :param local_cell: Name of local cell for which test will be started.
        :type local_cell: str
        :param rep_time_int: Reporting time interval (in seconds) between following measures.
        :type rep_time_int: int
        :param reception_slot: Reception slot parameter to run test with.
        :type reception_slot: str
        :param expectation_slot: Expectation slot parameter to run test with.
        :type expectation_slot str
        :param f0_sys_num: Format0 system number parameter with which test will be started. Works fine ONLY, if
        format parameter is set to 'F0', otherwise it may fail to set up pucch performance test, as there will be no
        parameter in WebUI.
        :type f0_sys_num: str
        :param f2_test_type: Format2 test type parameter with which test will be started. Works fine ONLY, if
        format parameter is set to 'F2', otherwise it may fail to set up pucch performance test, as there will be no
        parameter in WebUI.
        :type f2_test_type: str
        :param beam_id: ID of beam pattern  which will be used during test.
        :type beam_id: int
        :param ru_mode: Radio Unit mode, to be passed as exact value, e.g. "NR_Only".
        :type ru_mode: str
        :param physical_cell_id: Value of Physical cell ID which will be used during test.
        :type physical_cell_id: int
        :param pucch_format: PUCCH format parameter user wants to run test with.
        Should be provided as exact string value, e.g. 'F0'.
        :type pucch_format: str
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        """
        self._view_panel.start_pucch_test(local_cell, rep_time_int, reception_slot, expectation_slot, f0_sys_num,
                                          f2_test_type, beam_id, ru_mode, physical_cell_id, pucch_format, timeout)

    def start_prach_test(self, local_cell, rep_time_int, reception_slot, expectation_slot, beam_id, ru_mode,
                         physical_cell_id, preamble_index, accepted_timing_error, constant_offset, delay_pattern_duration,
                         prach_format, timeout):
        """
        Starts 5G Performance PRACH test on 5G Performance Test Page.
        :param local_cell: Name of local cell for which test will be started.
        :type local_cell: str
        :param rep_time_int: Reporting time interval (in seconds) between following measures.
        :type rep_time_int: int
        :param reception_slot: Reception slot parameter to run test with.
        :type reception_slot: int
        :param expectation_slot: Expectation slot parameter to run test with.
        :type expectation_slot int
        :param beam_id: ID of beam pattern  which will be used during test.
        :type beam_id: int
        :param ru_mode: Radio Unit mode, to be passed as exact value, e.g. "NR_Only".
        :type ru_mode: str
        :param physical_cell_id: Value of Physical cell ID which will be used during test.
        :type physical_cell_id: int
        :param preamble_index: Preamble index parameter user wants to run test with.
        :type preamble_index: int
        :param accepted_timing_error: Accepted timing error parameter to run test with.
        :type accepted_timing_error: int
        :param constant_offset: Constant offset parameter to run test with.
        :type constant_offset: int
        :param delay_pattern_duration: Delay pattern Duration parameter to run test with.
        :type delay_pattern_duration: int
        :param prach_format: PRACH format parameter with which test will be started.
        :type prach_format: str
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        """
        self._view_panel.start_prach_test(local_cell, rep_time_int, reception_slot, expectation_slot, beam_id, ru_mode,
                                          physical_cell_id, preamble_index, accepted_timing_error, constant_offset,
                                          delay_pattern_duration, prach_format, timeout)

    def wait_for_test_to_start(self, test_id, timeout):
        """
        Waits for test to be successfully started.
        :param test_id: Order number of test in Tests table.
        :type test_id: int
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        :raises ValueError: when test ID has incorrect value.
        """
        self._view_panel.wait_for_test_to_start(test_id, timeout)

    def stop_test(self, test_id, timeout):
        """
        Stops 5G performance test.
        :param test_id: Order number of test in Tests table.
        :type test_id: int
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        :raises ValueError: when test ID has incorrect value.
        """
        self._view_panel.stop_test(test_id, timeout)

    def wait_for_test_to_stop(self, test_id, timeout):
        """
        Waits for performance test to be successfully stopped.
        :param test_id: Order number of test in Tests table.
        :type test_id: int
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        :raises ValueError: when test ID has incorrect value.
        """
        self._view_panel.wait_for_test_to_stop(test_id, timeout)

    def get_carrier_frequency(self, timeout):
        """
        Gets value of carrier frequency from Performance Test Page.
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        :return: Value of carrier frequency if is available, None otherwise.
        :rtype: float
        """
        return self._view_panel.get_carrier_frequency(timeout)

    def is_test_available(self, local_cell, frc_index, timeout):
        """
        Checks whether test is visible in Tests table.
        :param local_cell: Name of local cell which checked test should contain.
        :type local_cell: str
        :param frc_index: Name of frc index which checked test should contain.
        :type frc_index: str
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        :return: True if test with given local cell and test model is available, False otherwise.
        :rtype: bool
        """
        return self._view_panel.is_test_available(local_cell, frc_index, timeout)

    def get_test_parameters_table(self, test_id, timeout):
        """
        Gets whole Test parameters table from R&D Mode > 5G Performance Test Page.
        :param test_id: Order number of test in Tests table.
        :type test_id: int
        :param timeout: Time to wait for individual steps of this operation to be completed.
        :type timeout: int
        :return: Dictionary with column names as keys and cell values as lists.
        :rtype: {str: [str, ]}
        :raises ValueError: when test ID has incorrect value.
        """
        return self._view_panel.get_test_parameters_table(test_id, timeout)

    def get_cumulative_results_table(self, test_id, timeout):
        """
        Gets whole Cumulative results table.
        :param test_id: Order number of test in Tests table; defaults to 1 (first test in table).
        :type test_id: int
        :param timeout: Time to wait for individual steps of this operation to be completed; defaults to 10 seconds.
        :type timeout: int
        :return: Dictionary with column names as keys and cell values as lists.
        :rtype: {str: [str, ]}
        :raises ValueError: when test ID has incorrect value.
        """
        return self._view_panel.get_cumulative_results_table(test_id, timeout)

    def get_partial_results_table(self, test_id, timeout):
        """
        Gets whole Partial results table.
        :param test_id: Order number of test in Tests table; defaults to 1 (first test in table).
        :type test_id: int
        :param timeout: Time to wait for individual steps of this operation to be completed; defaults to 10 seconds.
        :type timeout: int
        :return: Dictionary with column names as keys and cell values as lists.
        :rtype: {str: [str, ]}
        :raises ValueError: when test ID has incorrect value.
        """
        return self._view_panel.get_partial_results_table(test_id, timeout)

    def save_test_results(self, test_id, timeout):
        """
        Saves results of 5G uplink test.
        :param test_id: Order number of test in Tests table; defaults to 1 (first test in table).
        :type test_id: int
        :param timeout: Time to wait for individual steps of this operation to be completed; defaults to 10 seconds.
        :type timeout: int
        :raises ValueError: when test ID has incorrect value.
        """
        self._view_panel.save_test_results(test_id, timeout)


